                    {translate('workspace.common.moreFeatures').toLowerCase()}
                </TextLink>{' '}
                {variant === 'unlock' ? (
                    <Text style={[styles.textNormal, styles.colorMuted]}>{translate('workspace.rules.expenseReportRules.unlockFeatureEnableWorkflowsSubtitle', {featureName})}</Text>
